def test_keyboard_interrupt_while_exiting_is_aborted(monkeypatch, capsys):
    @click.command()
    def cli():
        pass

    exit_codes = []

    def exit_with_interrupt(exit_code):
        exit_codes.append(exit_code)

        if len(exit_codes) == 1:
            raise KeyboardInterrupt

        raise SystemExit(exit_code)

    monkeypatch.setattr("click.core.sys.exit", exit_with_interrupt)

    with pytest.raises(SystemExit) as exc_info:
        cli.main([])

    assert exc_info.value.code == 1
    assert exit_codes == [0, 1]
    assert capsys.readouterr().err == "\nAborted!\n"


